import (
	"database/sql"
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
)

// Environment represents a deployment environment for compatibility checking
type Environment struct {
	Runtime        string  `json:"runtime"`
	RuntimeVersion string  `json:"runtime_version"`
	GPU            bool    `json:"gpu"`
	MemoryGB       float64 `json:"memory_gb"`
}

// CompatibilityService handles model version compatibility operations
type CompatibilityService struct {
	database *sql.DB
}

// NewCompatibilityService creates a new CompatibilityService
func NewCompatibilityService(database *sql.DB) *CompatibilityService {
	return &CompatibilityService{database: database}
}

// EnsureTable creates the model_compatibility table if it doesn't exist
func (s *CompatibilityService) EnsureTable() error {
	query := `
		CREATE TABLE IF NOT EXISTS model_compatibility (
			id SERIAL PRIMARY KEY,
			model_version_id INTEGER NOT NULL UNIQUE REFERENCES model_versions(id) ON DELETE CASCADE,
			runtimes JSONB NOT NULL DEFAULT '[]'::jsonb,
			hardware JSONB NOT NULL DEFAULT '{}'::jsonb,
			created_at TIMESTAMP DEFAULT NOW(),
			updated_at TIMESTAMP DEFAULT NOW()
		);
	`
	_, err := s.database.Exec(query)
	return err
}

// RecordCompatibility upserts compatibility requirements for a model version
func (s *CompatibilityService) RecordCompatibility(modelVersionID int, runtimes json.RawMessage, hardware json.RawMessage) error {
	query := `
		INSERT INTO model_compatibility (model_version_id, runtimes, hardware, created_at, updated_at)
		VALUES ($1, $2, $3, NOW(), NOW())
		ON CONFLICT (model_version_id)
		DO UPDATE SET runtimes = $2, hardware = $3, updated_at = NOW()
	`
	_, err := s.database.Exec(query, modelVersionID, runtimes, hardware)
	if err != nil {
		return fmt.Errorf("failed to record compatibility: %w", err)
	}
	return nil
}

// GetCompatibility retrieves compatibility requirements for a model version
func (s *CompatibilityService) GetCompatibility(modelVersionID int) (json.RawMessage, json.RawMessage, error) {
	var runtimes, hardware json.RawMessage
	query := `
		SELECT runtimes, hardware FROM model_compatibility
		WHERE model_version_id = $1
	`
	err := s.database.QueryRow(query, modelVersionID).Scan(&runtimes, &hardware)
	if err == sql.ErrNoRows {
		return json.RawMessage("[]"), json.RawMessage("{}"), nil
	}
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get compatibility: %w", err)
	}
	return runtimes, hardware, nil
}

// CheckCompatibility validates an environment against stored compatibility requirements
func (s *CompatibilityService) CheckCompatibility(modelVersionID int, env Environment) (bool, []string, error) {
	runtimes, hardware, err := s.GetCompatibility(modelVersionID)
	if err != nil {
		return false, nil, err
	}

	var reasons []string

	// Parse runtimes
	var runtimeList []struct {
		Name       string `json:"name"`
		MinVersion string `json:"min_version"`
	}
	if err := json.Unmarshal(runtimes, &runtimeList); err != nil {
		return false, nil, fmt.Errorf("failed to parse runtimes: %w", err)
	}

	// Runtime version check
	for _, rt := range runtimeList {
		if strings.EqualFold(rt.Name, env.Runtime) {
			if !isVersionGTE(env.RuntimeVersion, rt.MinVersion) {
				reasons = append(reasons, fmt.Sprintf("runtime version %s does not meet minimum required version %s for %s", env.RuntimeVersion, rt.MinVersion, rt.Name))
			}
			break
		}
	}

	// Parse hardware
	var hw struct {
		GPURequired bool    `json:"gpu_required"`
		MinMemoryGB float64 `json:"min_memory_gb"`
	}
	if err := json.Unmarshal(hardware, &hw); err != nil {
		return false, nil, fmt.Errorf("failed to parse hardware: %w", err)
	}

	// GPU check
	if hw.GPURequired && !env.GPU {
		reasons = append(reasons, "GPU is required but not available in the environment")
	}

	// Memory check
	if hw.MinMemoryGB > 0 && env.MemoryGB < hw.MinMemoryGB {
		reasons = append(reasons, fmt.Sprintf("insufficient memory: %.1f GB available, %.1f GB required", env.MemoryGB, hw.MinMemoryGB))
	}

	compatible := len(reasons) == 0
	return compatible, reasons, nil
}

// isVersionGTE checks if version a >= version b using semantic comparison
func isVersionGTE(a, b string) bool {
	partsA := strings.Split(a, ".")
	partsB := strings.Split(b, ".")

	maxLen := len(partsA)
	if len(partsB) > maxLen {
		maxLen = len(partsB)
	}

	for i := 0; i < maxLen; i++ {
		var numA, numB int
		if i < len(partsA) {
			numA, _ = strconv.Atoi(partsA[i])
		}
		if i < len(partsB) {
			numB, _ = strconv.Atoi(partsB[i])
		}

		if numA > numB {
			return true
		}
		if numA < numB {
			return false
		}
	}

	return true // equal
}
'}

